  purchase?: Prisma.purchaseOmit
  purchaseitem?: Prisma.purchaseitemOmit
  purchasereturn?: Prisma.purchasereturnOmit
  purchasereturnitem?: Prisma.purchasereturnitemOmit
  stocktransaction?: Prisma.stocktransactionOmit
